import Component from 'flarum/common/Component';
import HotBoardItem from './HotBoardItem';

/**
 * 看板中的一列。列头沿用截图里的样式：图标 + 标题 + 下划线。
 */
export default class HotBoardColumn extends Component {
  view() {
    const {
      icon,
      title,
      items,
      meta,
      stacked
    } = this.attrs;
    return m("section", {
      className: "HotBoard-column"
    }, m("h3", {
      className: "HotBoard-heading"
    }, m("i", {
      className: `HotBoard-headingIcon ${icon}`,
      "aria-hidden": "true"
    }), m("span", {
      className: "HotBoard-headingText"
    }, title)), m("ul", {
      className: "HotBoard-list"
    }, items.map(discussion => m(HotBoardItem, {
      key: discussion.id(),
      discussion: discussion,
      meta: meta,
      stacked: stacked
    }))));
  }
}
flarum.reg.add('acme-hot-board', 'forum/components/HotBoardColumn', HotBoardColumn);