import Component from 'flarum/common/Component';
import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import Avatar from 'flarum/common/components/Avatar';
import humanTime from 'flarum/common/helpers/humanTime';
import { discussionImage } from '../../common/thumbnail';
import { viewsOf } from '../../common/metrics';

/**
 * 图片模式下的一个区块：图片轮播。
 *
 * 行为：
 *  - 图片占满整个区块（CSS 里留一定内边距），object-fit: cover
 *  - 图片下方是指示点，再下方是帖子标题与 meta
 *  - 按设定间隔自动切换，鼠标进入整个区块时暂停
 *  - 图片加载失败时回退到作者头像，不会留空白
 *  - 只有一条时不起定时器
 *
 * 标题由父组件传入（图片模式下统一是「图片帖子」）。
 */
export default class HotBoardCoverColumn extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    this.index = 0;
    this.paused = false;
    this.timer = null;
    /** 记录加载失败过的讨论 id，避免反复请求坏图 */
    this.failed = new Set();
    this.startTimer();
  }
  onremove() {
    this.stopTimer();
  }
  startTimer() {
    this.stopTimer();
    const items = this.attrs.items || [];
    const seconds = Number(this.attrs.interval) || 5;
    if (items.length < 2) return;
    this.timer = setInterval(() => {
      if (this.paused) return;
      this.go(this.index + 1);
    }, seconds * 1000);
  }
  stopTimer() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }
  go(next) {
    const items = this.attrs.items || [];
    if (!items.length) return;

    // 环形取模，兼容负数
    const n = (next % items.length + items.length) % items.length;
    if (n === this.index) return;
    this.index = n;
    m.redraw();
  }
  current() {
    const items = this.attrs.items || [];
    if (!items.length) return null;
    if (this.index >= items.length) this.index = 0;
    return items[this.index];
  }
  view() {
    const items = this.attrs.items || [];
    if (!items.length) return null;
    const discussion = this.current();
    const image = this.imageFor(discussion);
    const user = typeof discussion.user === 'function' ? discussion.user() : null;
    const href = app.route.discussion(discussion);
    return m("section", {
      className: "HotBoard-column HotBoard-column--cover",
      onmouseenter: () => {
        this.paused = true;
      },
      onmouseleave: () => {
        this.paused = false;
      }
    }, m("h3", {
      className: "HotBoard-heading"
    }, m("i", {
      className: `HotBoard-headingIcon ${this.attrs.icon}`,
      "aria-hidden": "true"
    }), m("span", {
      className: "HotBoard-headingText"
    }, this.attrs.title)), m("div", {
      className: "HotBoard-coverFrame"
    }, m(Link, {
      className: "HotBoard-coverLink",
      href: href,
      tabindex: "-1"
    }, image ? m("img", {
      key: 'img:' + image,
      className: "HotBoard-coverImage",
      src: image,
      alt: "",
      loading: "lazy",
      onerror: () => {
        this.failed.add(discussion.id());
        m.redraw();
      }
    }) : user ? m("span", {
      key: "avatar",
      className: "HotBoard-coverFallback"
    }, m(Avatar, {
      user: user,
      className: "HotBoard-coverAvatar"
    })) : m("span", {
      key: "empty",
      className: "HotBoard-coverFallback"
    }, m("i", {
      className: "fas fa-image",
      "aria-hidden": "true"
    })), m("span", {
      key: "scrim",
      className: "HotBoard-coverScrim",
      "aria-hidden": "true"
    }), m("span", {
      key: "caption",
      className: "HotBoard-coverCaption"
    }, m("span", {
      key: "title",
      className: "HotBoard-coverTitle"
    }, discussion.title()), m("span", {
      key: "meta",
      className: "HotBoard-coverMeta"
    }, this.metaContent(discussion)))), m("div", {
      className: "HotBoard-dots"
    }, items.length > 1 && items.map((item, i) => m("button", {
      type: "button",
      className: 'HotBoard-dot' + (i === this.index ? ' is-active' : ''),
      "aria-label": app.translator.trans('acme-hot-board.forum.slide_n', {
        current: i + 1,
        total: items.length
      }),
      onclick: () => this.go(i)
    })))));
  }
  imageFor(discussion) {
    if (this.failed.has(discussion.id())) return null;
    return discussionImage(discussion);
  }
  metaContent(discussion) {
    switch (this.attrs.meta) {
      case 'replies':
        return [m("i", {
          className: "far fa-comment",
          "aria-hidden": "true"
        }), m("span", {
          className: "HotBoard-metaValue"
        }, Number(discussion.commentCount() || 0))];
      case 'time':
        return humanTime(discussion.lastPostedAt());
      case 'views':
        return [m("i", {
          className: "far fa-eye",
          "aria-hidden": "true"
        }), m("span", {
          className: "HotBoard-metaValue"
        }, viewsOf(discussion))];
      default:
        return null;
    }
  }
}
flarum.reg.add('acme-hot-board', 'forum/components/HotBoardCoverColumn', HotBoardCoverColumn);